// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Clipboard Handler (Module 10 v2 — Step 10.7). * * Copies text to the system clipboard via [ClipboardManager]. * * ## Idempotent execution (Review 2 Elite 1) * * If the clipboard already contains the target text (case-sensitive), * skip the copy. Avoids redundant `setPrimaryClip` calls + clipboard * change notifications. * * ## Reversibility * * Not reversible — "undo" can't restore the previous clipboard content * without first capturing it. We don't capture pre-state because the * clipboard is shared across apps and could contain sensitive data the * user copied from another app (e.g., a password). * * If the user says "NOUS, undo that" after a clipboard copy, NOUS says: * "I copied 'X' to your clipboard — I can't restore what was there before * for privacy reasons." * * Implements plain [SystemOperationHandler]. * * ## Resource category * * Clipboard copies use [ResourceCategory.SETTINGS] — no shared hardware, * multiple clipboard ops in a batch run in parallel. * * ## Security * * Reading the clipboard is **restricted on Android 10+** — only the * foreground app or the IME can read it. [ClipboardService.getCurrentText] * works when NOUS is in the foreground (for idempotent check) but returns * null when NOUS is in the background. The handler degrades gracefully — * if `getCurrentText` returns null, skip the idempotent check and always * copy. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Clipboard</a> */class ClipboardHandler(    private val clipboardService: ClipboardService,) : StatelessSystemOperationHandler<SystemOperation.CopyToClipboard>() {    override val id: String = "clipboard"    override val displayName: String = "Clipboard Copy"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.SETTINGS    override fun isAvailable(): Boolean = true  // all devices have clipboard    override suspend fun execute(operation: SystemOperation.CopyToClipboard): Result<Unit> {        // Idempotent: skip if clipboard already has the target text.        val current = try {            clipboardService.getCurrentText()        } catch (t: Throwable) {            Timber.tag("ClipboardHandler").w("getCurrentText failed (likely background)", t)            null  // skip idempotent check — always copy        }        if (current == operation.text) {            return Result.Success(                data = Unit,                correlationId = CorrelationId.generate(),                durationNanos = 0,                warnings = listOf("idempotent_skip"),            )        }        val copied = clipboardService.copyText(operation.text)        return if (copied) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unknown("clipboard"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }}
